#!/usr/bin/env bash
# setup.sh — scaffold Workshop Downloader (Nuxt 4 + Nuxt UI v4 + Tauri v2, bun)
# Generated by Claude for milestone 1 of plans/create-a-nuxt-ancient-pizza.md
# Run from the project root with: bash setup.sh
set -euo pipefail

cd "$(dirname "$0")"

for tool in bun cargo git; do
  command -v "$tool" >/dev/null || { echo "missing '$tool' on PATH (bun: https://bun.sh, cargo: https://rustup.rs)"; exit 1; }
done

# 1. Fresh git repo for this project, so it doesn't land in the home-dir dotfiles repo.
[ -d .git ] || git init

# 2. Generate the Nuxt app from the Nuxt UI starter template. This folder isn't empty (it already has
#    plans/ and .gitignore), and "Override" could wipe it, so we generate into a temp subfolder and move
#    the files up in step 3. Prompts left to you: "browse and install modules?" (answer as you like).
bunx create-nuxt@latest .scaffold-nuxt --template ui --packageManager bun --no-gitInit --no-install

# 3. Move the generated files into the project root. Anything that already exists here (e.g. .gitignore)
#    is NOT overwritten: the template's copy is kept as <name>.nuxt-template for Claude to merge.
shopt -s dotglob
for f in .scaffold-nuxt/*; do
  name="$(basename "$f")"
  if [ -e "$name" ]; then mv "$f" "$name.nuxt-template"; else mv "$f" .; fi
done
shopt -u dotglob
rmdir .scaffold-nuxt

# 4. Install the Nuxt deps, then add vueuse, drizzle and vitest.
bun install
bun add @vueuse/core @vueuse/nuxt drizzle-orm
bun add -D drizzle-kit vitest

# 5. Tauri v2: CLI + JS API, then `tauri init` with the values from the plan.
bun add -D @tauri-apps/cli@latest
bun add @tauri-apps/api@latest
bun tauri init \
  --app-name "workshop-downloader" \
  --window-title "Workshop Downloader" \
  --frontend-dist "../.output/public" \
  --dev-url "http://localhost:3000" \
  --before-dev-command "bun run sidecar && bun run dev" \
  --before-build-command "bun run sidecar && bun run generate"

# 6. Tauri plugins from the plan (each adds the Rust crate + JS package and registers it).
for plugin in sql shell dialog fs opener log single-instance; do
  bun tauri add "$plugin"
done
# The sql plugin needs its engine picked explicitly.
cargo add tauri-plugin-sql --features sqlite --manifest-path src-tauri/Cargo.toml

# 7. fswatch sidecar crate (workspace wiring with src-tauri is done by Claude afterwards).
cargo new crates/fswatch --bin --vcs none
cargo add notify jwalk serde_json --manifest-path crates/fswatch/Cargo.toml
cargo add serde --features derive --manifest-path crates/fswatch/Cargo.toml

echo "setup.sh done — tell Claude to finish the setup."
